css:
@keyframes slide-in {
  from {
    opacity: 0;
    transform: translateX(-16px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.list {
  display: grid;
  gap: 8px;
  max-width: 360px;
  margin: 24px;
  padding: 0;
  list-style: none;
  font-family: system-ui, sans-serif;
}

.row {
  --i: 0;

  padding: 12px 16px;
  border-radius: 8px;
  background-color: #fff7ed;
  animation: slide-in 400ms ease-out both;
  animation-delay: calc(var(--i) * 80ms);
}

.row:nth-child(2) {
  --i: 1;
}

.row:nth-child(3) {
  --i: 2;
}

.row:nth-child(4) {
  --i: 3;
}

@media (prefers-reduced-motion: reduce) {
  .row {
    animation: none;
  }
}
